def draw_bar(stdscr, y, x, width, label, pcts, colors, total_label, monochrome=False, use_unicode=True):
    """Draw a meter bar like: Label[||||||||     value]"""
    bracket_width = width - len(label) - 2  # subtract label and []
    if bracket_width <= 0:
        return

    # Draw label
    try:
        stdscr.addstr(y, x, label, curses.color_pair(COLOR_METER_TEXT) | curses.A_BOLD)
        stdscr.addch(y, x + len(label), '[', curses.color_pair(COLOR_DEFAULT))

        # Draw bar contents
        fill_width = bracket_width - len(total_label) - 1
        if fill_width <= 0:
            fill_width = bracket_width

        # Calculate fill amounts
        total_pct = min(100.0, sum(pcts))
        filled = int(fill_width * total_pct / 100.0)

        bar_x = x + len(label) + 1
        if use_unicode:
            bar_char = '|'
        else:
            bar_char = '|'

        pos = 0
        for i, (pct, color) in enumerate(zip(pcts, colors)):
            n = int(fill_width * pct / 100.0)
            if i == len(pcts) - 1:
                n = filled - pos
            for j in range(n):
                if pos < fill_width:
                    try:
                        stdscr.addch(y, bar_x + pos, bar_char,
                                    curses.color_pair(color) | curses.A_BOLD)
                    except:
                        pass
                    pos += 1

        # Fill rest with spaces
        for j in range(pos, fill_width):
            try:
                stdscr.addch(y, bar_x + j, ' ', curses.color_pair(COLOR_DEFAULT))
            except:
                pass

        # Draw total label right-aligned
        total_x = bar_x + fill_width + 1
        try:
            stdscr.addstr(y, total_x, total_label, curses.color_pair(COLOR_METER_VALUE) | curses.A_BOLD)
        except:
            pass

        end_x = x + len(label) + 1 + bracket_width
        try:
            stdscr.addch(y, end_x, ']', curses.color_pair(COLOR_DEFAULT))
        except:
            pass
    except:
        pass


def draw_header(stdscr, sysinfo, height, width, show_meters=True, use_unicode=True, monochrome=False):
    """Draw the htop header with CPU/Memory/Swap meters and info."""
    if not show_meters:
        return 0

    # Row 0: CPU bar
    avg_pct = sysinfo.get_avg_cpu_percent()
    cpu_label = '  Avg'
    cpu_info = sysinfo.cpu_percent.get('cpu', {})
    user_pct = cpu_info.get('user', 0) / max(1, cpu_info.get('total', 1)) * 100 if cpu_info.get('total', 0) > 0 else 0
    sys_pct = cpu_info.get('system', 0) / max(1, cpu_info.get('total', 1)) * 100 if cpu_info.get('total', 0) > 0 else 0

    # Right-side info: Tasks, Load average
    tasks_str = 'Tasks: %d, %d thr, %d kthr; %d running' % (
        sysinfo.tasks_total if hasattr(sysinfo, 'tasks_total') else 0,
        sysinfo.thread_count if hasattr(sysinfo, 'thread_count') else 0,
        sysinfo.kernel_thread_count if hasattr(sysinfo, 'kernel_thread_count') else 0,
        sysinfo.running_tasks if hasattr(sysinfo, 'running_tasks') else 0,
    )
    load_str = 'Load average: %.2f %.2f %.2f' % tuple(sysinfo.load_avg)
    uptime_str = 'Uptime: ' + format_uptime(sysinfo.uptime)

    # CPU bar takes left portion, info takes right
    # Calculate widths
    left_w = width - len(tasks_str) - 1
    if left_w < 20:
        left_w = 20

    cpu_total_str = '%.1f%%' % avg_pct
    try:
        draw_bar(stdscr, 0, 0, left_w, cpu_label,
                [user_pct, sys_pct],
                [COLOR_CPU2, COLOR_CPU3],
                cpu_total_str, monochrome, use_unicode)
        stdscr.addstr(0, width - len(tasks_str), tasks_str)
    except:
        pass

    # Row 1: Memory bar
    if sysinfo.mem_total > 0:
        mem_used_pct = 100.0 * sysinfo.mem_used / sysinfo.mem_total
        mem_shared_pct = 100.0 * sysinfo.mem_shared / sysinfo.mem_total
        mem_buffers_pct = 100.0 * sysinfo.mem_buffers / sysinfo.mem_total
        mem_cached_pct = 100.0 * sysinfo.mem_cached / sysinfo.mem_total
    else:
        mem_used_pct = mem_shared_pct = mem_buffers_pct = mem_cached_pct = 0.0

    mem_used_str = '%s/%s' % (human_size(sysinfo.mem_used // 1024), human_size(sysinfo.mem_total // 1024))
    mem_label = '  Mem'

    left_w2 = width - len(load_str) - 1
    if left_w2 < 20:
        left_w2 = 20

    try:
        draw_bar(stdscr, 1, 0, left_w2, mem_label,
                [mem_used_pct, mem_shared_pct, mem_buffers_pct, mem_cached_pct],
                [COLOR_MEM1, COLOR_MEM2, COLOR_MEM3, COLOR_MEM4],
                mem_used_str, monochrome, use_unicode)
        stdscr.addstr(1, width - len(load_str), load_str)
    except:
        pass

