        swap_cached_pct = 100.0 * sysinfo.swap_cached / sysinfo.swap_total
    else:
        swap_used_pct = swap_cached_pct = 0.0

    swap_used_str = '%s/%s' % (human_size(sysinfo.swap_used // 1024), human_size(sysinfo.swap_total // 1024))
    swap_label = '  Swp'

