                [COLOR_SWAP1, COLOR_SWAP2],
                swap_used_str, monochrome, use_unicode)
        stdscr.addstr(2, width - len(uptime_str), uptime_str)
    except:
        pass

    return 3  # header takes 3 rows


def format_process_value(proc, col_name, sysinfo, tree_view=False):
    """Format a process column value as a string."""
    if col_name == 'PID':
        return str(proc.pid)
    elif col_name == 'USER':
        return proc.username[:10]
    elif col_name == 'PRIORITY':
        if proc.priority == -100:
            return 'RT'
        return str(proc.priority)
    elif col_name == 'NICE':
        return str(proc.nice)
    elif col_name == 'M_VIRT':
        return human_size(proc.virt)
    elif col_name == 'M_RESIDENT':
        return human_size(proc.res)
    elif col_name == 'M_SHARE':
        return human_size(proc.shared)
    elif col_name == 'STATE':
        return proc.state
    elif col_name == 'PERCENT_CPU':
        return '%.1f' % proc.cpu_percent
    elif col_name == 'PERCENT_MEM':
        return '%.1f' % proc.mem_percent
    elif col_name == 'TIME':
        return format_time(proc.utime + proc.stime)
    elif col_name == 'Command':
        cmd = proc.cmdline if proc.cmdline else proc.comm
        return cmd
    elif col_name == 'PPID':
        return str(proc.ppid)
    elif col_name == 'PGRP':
        return str(proc.pgrp)
    elif col_name == 'SESSION':
        return str(proc.session)
    elif col_name == 'TTY':
        return str(proc.tty)
    elif col_name == 'TPGID':
        return str(proc.tpgid)
    elif col_name == 'MINFLT':
        return str(proc.minflt)
    elif col_name == 'MAJFLT':
        return str(proc.majflt)
    elif col_name == 'UTIME':
        return format_time(proc.utime)
    elif col_name == 'STIME':
        return format_time(proc.stime)
    elif col_name == 'STARTTIME':
        # Format as HH:MM:SS or month/day
        try:
            boot = sysinfo.boot_time
            start_secs = boot + proc.starttime / CLOCK_TICKS
            t = time.localtime(start_secs)
            now = time.time()
            if now - start_secs > 86400:
                return time.strftime('%b%d', t)
            return time.strftime('%H:%M:%S', t)
        except:
            return '?'
    elif col_name == 'PROCESSOR':
        return str(proc.processor)
    elif col_name == 'NLWP':
        return str(proc.nlwp)
    elif col_name == 'TGID':
        return str(proc.tgid)
    elif col_name == 'PERCENT_NORM_CPU':
        ncpu = max(1, sysinfo.num_cpus)
        return '%.1f' % (proc.cpu_percent / ncpu)
    elif col_name == 'RCHAR':
        return human_size(proc.rchar // 1024)
    elif col_name == 'WCHAR':
        return human_size(proc.wchar // 1024)
    elif col_name == 'SYSCR':
        return str(proc.syscr)
    elif col_name == 'SYSCW':
        return str(proc.syscw)
    elif col_name == 'RBYTES':
        return human_size(proc.rbytes // 1024)
    elif col_name == 'WBYTES':
        return human_size(proc.wbytes // 1024)
    elif col_name == 'CNCLWB':
        return human_size(proc.cnclwb // 1024)
    elif col_name == 'IO_READ_RATE':
        return '%.2f B/s' % proc.io_read_rate if proc.io_read_rate < 1024 else human_size_bytes(int(proc.io_read_rate)) + '/s'
    elif col_name == 'IO_WRITE_RATE':
        return '%.2f B/s' % proc.io_write_rate if proc.io_write_rate < 1024 else human_size_bytes(int(proc.io_write_rate)) + '/s'
    elif col_name == 'IO_RATE':
        rate = proc.io_read_rate + proc.io_write_rate
        return '%.2f B/s' % rate if rate < 1024 else human_size_bytes(int(rate)) + '/s'
    elif col_name == 'CGROUP':
        return proc.cgroup or '-'
    elif col_name == 'OOM':
        return str(proc.oom_score)
    elif col_name == 'IO_PRIORITY':
        return '%s%d' % ('B', proc.io_prio_class) if proc.io_prio_class else 'B4'
    elif col_name == 'CTXT':
        return str(proc.ctxt_switches)
    elif col_name == 'COMM':
        return proc.comm
    else:
        return '-'

