class Screen:
    """Represents a screen tab with its columns."""

    def __init__(self, name, columns):
        self.name = name
        self.columns = columns
        self.scroll_x = 0


class HtopApp:
    """Main htop application."""

    def __init__(self, args):
        self.args = args
        self.sysinfo = SystemInfo()
        self.proclist = ProcessList(self.sysinfo)

        # Apply arguments
        self.delay = 15  # tenths of a second (default 1.5s)
        if args.delay:
            d = int(args.delay)
            if d < 1:
                d = 1
            if d > 100:
                d = 100
            self.delay = d

        self.monochrome = args.no_color
        self.use_unicode = not args.no_unicode
        self.show_meters = not args.no_meters
        self.show_function_bar = not args.no_function_bar
        self.max_iterations = args.max_iterations
        self.readonly = args.readonly
        self.no_mouse = args.no_mouse

        if args.filter:
            self.proclist.filter_string = args.filter

        if args.pid:
            pids = set()
            for p in args.pid.split(','):
                try:
                    pids.add(int(p.strip()))
                except:
                    pass
            self.proclist.filter_pids = pids if pids else None

        if args.user is not None:
            if args.user == '':
                # Use current user
                try:
                    self.proclist.filter_user = pwd.getpwuid(os.getuid()).pw_name
                except:
                    self.proclist.filter_user = str(os.getuid())
            else:
                self.proclist.filter_user = args.user

        if args.sort_key:
            self.proclist.sort_key = args.sort_key

        if args.tree:
            self.proclist.tree_view = True

        # Screens
        self.screens = [
            Screen('Main', list(MAIN_COLUMNS)),
            Screen('I/O', list(IO_COLUMNS)),
        ]
        self.current_screen = 0

        # UI state
        self.selected_idx = 0
        self.scroll_y = 0
        self.iteration = 0
        self.paused = False
        self.search_string = ''
        self.search_mode = False
        self.filter_mode = False
        self.highlight_changes = args.highlight_changes

        # Column widths cache
        self._col_widths = {}

        # Task counts
        self.sysinfo.tasks_total = 0
        self.sysinfo.running_tasks = 0
        self.sysinfo.thread_count = 0
        self.sysinfo.kernel_thread_count = 0

    def run(self, stdscr):
        """Main application loop."""
        # Initialize curses
        curses.cbreak()
        curses.noecho()
        stdscr.keypad(True)

        if not self.no_mouse:
            try:
                curses.mousemask(curses.ALL_MOUSE_EVENTS | curses.REPORT_MOUSE_POSITION)
            except:
                pass

        init_colors(self.monochrome)
        curses.curs_set(0)  # Hide cursor

        # Set timeout for getch
        stdscr.timeout(int(self.delay * 100))  # Convert tenths to ms

        self.height, self.width = stdscr.getmaxyx()

        # Initial update
        self.sysinfo.update()
        self.proclist.proclist_update_sysinfo()
        self.proclist.update()

        self.iteration = 1

        while True:
            if not self.paused:
                # Redraw
                self.draw(stdscr)

            # Get input
            try:
                key = stdscr.getch()
            except KeyboardInterrupt:
                break

            if key == -1:
                # Timeout - update
                if not self.paused:
                    self.sysinfo.update()
                    self.proclist.proclist_update_sysinfo()
                    self.proclist.update()
                    self.iteration += 1
                    if self.max_iterations and self.iteration > self.max_iterations:
                        break
                continue

            # Check for resize
            new_h, new_w = stdscr.getmaxyx()
            if new_h != self.height or new_w != self.width:
                self.height = new_h
                self.width = new_w
                stdscr.clear()

            # Handle input
            result = self.handle_key(stdscr, key)
            if result == 'quit':
                break

            # Update display after key
            self.sysinfo.update()
            self.proclist.proclist_update_sysinfo()
            self.proclist.update()
            self.draw(stdscr)
            self.iteration += 1

            if self.max_iterations and self.iteration > self.max_iterations:
                break

        # Clean up
        curses.curs_set(1)

    def draw(self, stdscr):
        """Draw the complete UI."""
        stdscr.erase()
        h, w = self.height, self.width

        # Draw header
        header_rows = 0
        if self.show_meters:
            header_rows = draw_header(stdscr, self.sysinfo, h, w, 
                                       self.show_meters, self.use_unicode, self.monochrome)

        # Draw blank line after header
        try:
            stdscr.addstr(header_rows, 0, ' ' * min(w, 200))
        except:
            pass

        # Draw tab bar
        tab_row = header_rows + 1
        self.draw_tabs(stdscr, tab_row, w)

        # Draw process list
        list_start = tab_row + 1
        list_height = h - list_start
        if self.show_function_bar and not self.search_mode and not self.filter_mode:
            list_height -= 1

        screen = self.screens[self.current_screen]
        self.draw_process_list(stdscr, list_start, list_height, w, screen)

        # Draw function bar
        if self.show_function_bar:
            func_row = h - 1
            if self.search_mode:
                self.draw_search_bar(stdscr, func_row, w)
            elif self.filter_mode:
                self.draw_filter_bar(stdscr, func_row, w)
            else:
                self.draw_function_bar(stdscr, func_row, w)

        stdscr.refresh()

    def draw_tabs(self, stdscr, row, width):
        """Draw screen tabs."""
        try:
            x = 0
            for i, screen in enumerate(self.screens):
                tab_str = ' [%s] ' % screen.name if i != self.current_screen else ' [%s] ' % screen.name
                if i == self.current_screen:
                    attr = curses.color_pair(COLOR_PANEL_HEADER_FOCUS) | curses.A_BOLD
                else:
                    attr = curses.color_pair(COLOR_PANEL_HEADER)
                if x + len(tab_str) < width:
                    stdscr.addstr(row, x, tab_str, attr)
                x += len(tab_str)
        except:
            pass

    def draw_process_list(self, stdscr, start_row, num_rows, width, screen):
        """Draw the process list."""
        if num_rows <= 1:
            return

        columns = screen.columns
        tree_view = self.proclist.tree_view and self.current_screen == 0

        # Calculate column widths
        col_data = []
        for col_name in columns:
            if col_name not in COLUMNS:
                continue
            col = COLUMNS[col_name]
            if col_name == 'Command':
                w = 20  # will be computed later
            else:
                w = col['width']
            col_data.append((col_name, col, w))

        # Fixed columns total width
        fixed_width = sum(c[2] + 1 for c in col_data[:-1]) if col_data else 0
        if col_data:
            last_col_width = max(20, width - fixed_width)
        else:
            last_col_width = width

        # Draw column header
        header_attr = curses.color_pair(COLOR_PANEL_HEADER) | curses.A_BOLD
        x = 0
        header_str = ''

        for i, (col_name, col, cw) in enumerate(col_data):
            is_last = (i == len(col_data) - 1)
            if is_last:
                cw = last_col_width

            title = col['title']
            if col_name == 'PID' and tree_view:
                title = 'PID+'

            if col_name == self.proclist.sort_key:
                attr = curses.color_pair(COLOR_PANEL_HEADER_FOCUS) | curses.A_BOLD
            else:
                attr = header_attr

            if col['align'] == 'right':
                s = title.rjust(cw)
            else:
                s = title.ljust(cw)

            try:
                stdscr.addstr(start_row, x, s[:cw], attr)
            except:
                pass
            x += cw
            if not is_last:
                try:
                    stdscr.addch(start_row, x, ' ', header_attr)
                except:
                    pass
                x += 1

        # Draw processes
        procs = self.proclist.display_list

        # Apply search filter to visible items
        if self.search_string:
            search_lower = self.search_string.lower()
            visible = []
            for p in procs:
                cmd = (p.cmdline or p.comm).lower()
                if search_lower in cmd:
                    visible.append(p)
        else:
            visible = procs

        total_procs = len(visible)

        # Clamp selected
        if self.selected_idx >= total_procs:
            self.selected_idx = max(0, total_procs - 1)

        # Adjust scroll
        list_rows = num_rows - 1  # subtract header row
        if self.selected_idx < self.scroll_y:
            self.scroll_y = self.selected_idx
        elif self.selected_idx >= self.scroll_y + list_rows:
            self.scroll_y = self.selected_idx - list_rows + 1

        if self.scroll_y < 0:
            self.scroll_y = 0

        # Draw each visible process
        for row_idx in range(list_rows):
            proc_idx = self.scroll_y + row_idx
            row = start_row + 1 + row_idx

            if row >= self.height - (1 if self.show_function_bar else 0):
                break

            if proc_idx >= total_procs:
                # Clear remaining rows
                try:
                    stdscr.addstr(row, 0, ' ' * min(width, 200))
                except:
                    pass
                continue

            proc = visible[proc_idx]
            is_selected = (proc_idx == self.selected_idx)

            # Determine process color
            if is_selected:
                base_attr = curses.color_pair(COLOR_PANEL_SELECTION_FOCUS) | curses.A_BOLD
                base_default_attr = base_attr
            elif proc.tagged:
                base_attr = curses.color_pair(COLOR_PROCESS_TAG) | curses.A_BOLD
                base_default_attr = base_attr
            elif proc.state == 'Z':
                base_attr = curses.color_pair(COLOR_ZOMBIE) | curses.A_BOLD
                base_default_attr = base_attr
            elif proc.state == 'R':
                base_attr = curses.color_pair(COLOR_RUNNING_PROCESS) | curses.A_BOLD
                base_default_attr = base_attr
            elif proc.is_kernel_thread:
                base_attr = curses.color_pair(COLOR_KERNEL_THREAD)
                base_default_attr = base_attr
            elif proc.is_userland_thread:
                base_attr = curses.color_pair(COLOR_USERLAND_THREAD)
                base_default_attr = base_attr
            else:
                base_attr = curses.color_pair(COLOR_DEFAULT)
                base_default_attr = base_attr

            # Draw each column
            x = 0
            for i, (col_name, col, cw) in enumerate(col_data):
                is_last = (i == len(col_data) - 1)
                if is_last:
                    cw = max(20, width - x)

                value = format_process_value(proc, col_name, self.sysinfo, tree_view)

                if col_name == 'Command' and tree_view:
                    # Add tree prefix
                    prefix = self._get_tree_prefix(proc)
                    value = prefix + value

                # Truncate or pad
                if col['align'] == 'right' and not is_last:
                    s = value.rjust(cw)[:cw]
                else:
                    if is_last:
                        s = value[:max(1, width - x)]
                    else:
                        s = value.ljust(cw)[:cw]

                try:
                    stdscr.addstr(row, x, s, base_default_attr)
                except:
                    pass

                x += cw
                if not is_last and x < width:
                    try:
                        stdscr.addch(row, x, ' ', base_default_attr)
                    except:
                        pass
                    x += 1

            # Fill rest of line if selected
            if is_selected and x < width:
                try:
                    stdscr.addstr(row, x, ' ' * (width - x), base_default_attr)
                except:
                    pass

    def _get_tree_prefix(self, proc):
        """Get tree view prefix for a process."""
        if proc.depth == 0:
            return ''
        parts = []
        # Build prefix based on depth
        parts.append('`- ')
        if proc.depth > 1:
            parts = ['   ' * (proc.depth - 1)] + parts
        return ''.join(parts)

    def draw_function_bar(self, stdscr, row, width):
        """Draw the F1-F10 function bar at bottom."""
        tree_view = self.proclist.tree_view

        if self.current_screen == 0:
            f5_label = 'Tree  ' if not tree_view else 'List  '
        else:
            f5_label = 'Tree  '

        funcs = [
            ('F1', 'Help  '),
            ('F2', 'Setup '),
            ('F3', 'Search'),
            ('F4', 'Filter'),
            ('F5', f5_label),
            ('F6', 'SortBy'),
            ('F7', 'Nice -'),
            ('F8', 'Nice +'),
            ('F9', 'Kill  '),
            ('F10', 'Quit  '),
        ]

        x = 0
        for key_label, func_label in funcs:
            key_attr = curses.color_pair(COLOR_FUNCTION_KEY) | curses.A_BOLD
            func_attr = curses.color_pair(COLOR_FUNCTION_BAR)
            try:
                stdscr.addstr(row, x, key_label, key_attr)
                x += len(key_label)
                stdscr.addstr(row, x, func_label, func_attr)
                x += len(func_label)
            except:
                pass

    def draw_search_bar(self, stdscr, row, width):
        """Draw search bar at bottom."""
        try:
            label = 'Search: '
            stdscr.addstr(row, 0, label, curses.color_pair(COLOR_FUNCTION_BAR) | curses.A_BOLD)
            stdscr.addstr(row, len(label), self.search_string, curses.color_pair(COLOR_FUNCTION_BAR))
            # cursor position
            curses.curs_set(1)
        except:
            pass

    def draw_filter_bar(self, stdscr, row, width):
        """Draw filter bar at bottom."""
        try:
            label = 'Filter: '
            stdscr.addstr(row, 0, label, curses.color_pair(COLOR_FUNCTION_BAR) | curses.A_BOLD)
            stdscr.addstr(row, len(label), self.proclist.filter_string, curses.color_pair(COLOR_FUNCTION_BAR))
            curses.curs_set(1)
        except:
            pass

    def handle_key(self, stdscr, key):
        """Handle a keypress. Returns 'quit' to exit."""
        # Search mode
        if self.search_mode:
            return self.handle_search_key(key)

        # Filter mode
        if self.filter_mode:
            return self.handle_filter_key(key)

        procs = self.proclist.display_list
        total = len(procs)

        # Navigation keys
        if key in (curses.KEY_UP, ord('k') | 0x200):  # Up or Alt-k  
            if self.selected_idx > 0:
                self.selected_idx -= 1
        elif key == curses.KEY_UP:
            if self.selected_idx > 0:
                self.selected_idx -= 1
        elif key in (curses.KEY_DOWN,):
            if self.selected_idx < total - 1:
                self.selected_idx += 1
        elif key == curses.KEY_PPAGE:
            list_rows = self._list_height()
            self.selected_idx = max(0, self.selected_idx - list_rows)
            self.scroll_y = max(0, self.scroll_y - list_rows)
        elif key == curses.KEY_NPAGE:
            list_rows = self._list_height()
            self.selected_idx = min(total - 1, self.selected_idx + list_rows)
        elif key == curses.KEY_HOME:
            self.selected_idx = 0
            self.scroll_y = 0
        elif key == curses.KEY_END:
            self.selected_idx = max(0, total - 1)
        elif key == curses.KEY_LEFT:
            screen = self.screens[self.current_screen]
            if screen.scroll_x > 0:
                screen.scroll_x -= 1
        elif key == curses.KEY_RIGHT:
            screen = self.screens[self.current_screen]
            screen.scroll_x += 1

        # Tab - switch screens
        elif key == ord('\t'):
            self.current_screen = (self.current_screen + 1) % len(self.screens)
        elif key == curses.KEY_BTAB:
            self.current_screen = (self.current_screen - 1) % len(self.screens)

        # Quit
        elif key in (ord('q'), curses.KEY_F10):
            return 'quit'

        # Help
        elif key in (ord('h'), ord('?'), curses.KEY_F1):
            self.show_help(stdscr)

        # Setup
        elif key in (ord('S'), ord('C'), curses.KEY_F2):
            self.show_setup(stdscr)

        # Search
        elif key in (ord('/'), curses.KEY_F3):
            self.search_mode = True
            self.search_string = ''
            curses.curs_set(1)

        # Filter
        elif key in (ord('\\'), curses.KEY_F4):
            self.filter_mode = True
            curses.curs_set(1)

        # Tree toggle
        elif key in (ord('t'), curses.KEY_F5):
            self.proclist.tree_view = not self.proclist.tree_view
            self.proclist.rebuild_display_list()

        # Sort column selection
        elif key in (curses.KEY_F6, ord('>'), ord('.')):
            self.show_sort_panel(stdscr)

        # Sort by PID
        elif key == ord('N'):
            self.proclist.sort_key = 'PID'
            self.proclist.sort_reverse = False
            self.proclist.rebuild_display_list()

        # Sort by CPU
        elif key == ord('P'):
            self.proclist.sort_key = 'PERCENT_CPU'
            self.proclist.sort_reverse = True
            self.proclist.rebuild_display_list()

        # Sort by MEM
        elif key == ord('M'):
            self.proclist.sort_key = 'M_RESIDENT'
            self.proclist.sort_reverse = True
            self.proclist.rebuild_display_list()

        # Sort by TIME
        elif key == ord('T'):
            self.proclist.sort_key = 'TIME'
            self.proclist.sort_reverse = True
            self.proclist.rebuild_display_list()

        # Invert sort
        elif key == ord('I'):
            self.proclist.sort_reverse = not self.proclist.sort_reverse
            self.proclist.rebuild_display_list()

        # Space - tag process
        elif key == ord(' '):
            if procs and 0 <= self.selected_idx < total:
                procs[self.selected_idx].tagged = not procs[self.selected_idx].tagged
                if self.selected_idx < total - 1:
                    self.selected_idx += 1

        # c - tag process and children
        elif key == ord('c'):
            if procs and 0 <= self.selected_idx < total:
                proc = procs[self.selected_idx]
                self._tag_with_children(proc, True)

        # U - untag all
        elif key == ord('U'):
            for p in self.proclist.processes.values():
                p.tagged = False

        # F - cursor follows
        elif key == ord('F'):
            pass  # TODO

        # Hide/show threads
        elif key == ord('H'):
            self.proclist.show_threads = not self.proclist.show_threads
            self.proclist.rebuild_display_list()

        # Hide/show kernel threads
        elif key == ord('K'):
            self.proclist.show_kernel_threads = not self.proclist.show_kernel_threads
            self.proclist.rebuild_display_list()

        # Show processes of a single user
        elif key == ord('u'):
            self.show_user_filter(stdscr)

        # Pause
        elif key == ord('Z'):
            self.paused = not self.paused

        # Nice -
        elif key in (ord(']'), curses.KEY_F7):
            if not self.readonly and procs and 0 <= self.selected_idx < total:
                self.change_nice(procs[self.selected_idx], -1)

        # Nice +
        elif key in (ord('['), curses.KEY_F8):
            if not self.readonly and procs and 0 <= self.selected_idx < total:
                self.change_nice(procs[self.selected_idx], 1)

        # Kill
        elif key in (ord('k'), curses.KEY_F9):
            if not self.readonly and procs and 0 <= self.selected_idx < total:
                self.kill_process(stdscr, procs[self.selected_idx])

        # Toggle path
        elif key == ord('p'):
            pass  # TODO

        # Toggle merged command
        elif key == ord('m'):
            pass  # TODO

        # Show env
        elif key == ord('e'):
            if procs and 0 <= self.selected_idx < total:
                self.show_env(stdscr, procs[self.selected_idx])

        # Tree expand/collapse
        elif key == ord('+'):
            if procs and 0 <= self.selected_idx < total:
                procs[self.selected_idx].collapsed = False
                self.proclist.rebuild_display_list()
        elif key == ord('-'):
            if procs and 0 <= self.selected_idx < total:
                procs[self.selected_idx].collapsed = True
                self.proclist.rebuild_display_list()
        elif key == ord('*'):
            # Toggle all
            for p in self.proclist.processes.values():
                p.collapsed = not p.collapsed
            self.proclist.rebuild_display_list()

        # Hide meters
        elif key == ord('#'):
            self.show_meters = not self.show_meters

        # Mouse
        elif key == curses.KEY_MOUSE:
            try:
                _, mx, my, _, bstate = curses.getmouse()
                self.handle_mouse(mx, my, bstate)
            except:
                pass

        # Ctrl-A / ^
        elif key in (1, ord('^')):  # Ctrl-A
            screen = self.screens[self.current_screen]
            screen.scroll_x = 0

        # Ctrl-E / $
        elif key in (5, ord('$')):  # Ctrl-E
            pass  # scroll to end

        # Wrap command
        elif key == ord('w'):
            if procs and 0 <= self.selected_idx < total:
                self.show_wrapped_command(stdscr, procs[self.selected_idx])

        # Resize
        elif key == curses.KEY_RESIZE:
            self.height, self.width = stdscr.getmaxyx()
            stdscr.clear()

        return None

    def handle_search_key(self, key):
        """Handle key in search mode."""
        if key in (curses.KEY_ENTER, 10, 13, 27):  # Enter or Escape
            if key == 27:
                self.search_string = ''
            self.search_mode = False
            curses.curs_set(0)
        elif key in (curses.KEY_BACKSPACE, 127, 8):
            if self.search_string:
                self.search_string = self.search_string[:-1]
        elif 32 <= key < 128:
            self.search_string += chr(key)
        return None

    def handle_filter_key(self, key):
        """Handle key in filter mode."""
        if key in (curses.KEY_ENTER, 10, 13, 27):  # Enter or Escape
            if key == 27:
                self.proclist.filter_string = ''
            self.filter_mode = False
            curses.curs_set(0)
            self.proclist.rebuild_display_list()
        elif key in (curses.KEY_BACKSPACE, 127, 8):
            if self.proclist.filter_string:
                self.proclist.filter_string = self.proclist.filter_string[:-1]
                self.proclist.rebuild_display_list()
        elif 32 <= key < 128:
            self.proclist.filter_string += chr(key)
            self.proclist.rebuild_display_list()
        return None

    def handle_mouse(self, mx, my, bstate):
        """Handle mouse events."""
        header_rows = 3 if self.show_meters else 0
        list_start = header_rows + 2  # +1 for blank, +1 for tab row

        if my >= list_start + 1:  # +1 for column header
            proc_idx = self.scroll_y + (my - list_start - 1)
            if 0 <= proc_idx < len(self.proclist.display_list):
                self.selected_idx = proc_idx

    def _list_height(self):
        """Get the height of the process list area."""
        header_rows = 3 if self.show_meters else 0
        list_start = header_rows + 2
        bottom_rows = 1 if self.show_function_bar else 0
        return max(1, self.height - list_start - 1 - bottom_rows)

    def _tag_with_children(self, proc, tag):
        """Tag a process and all its children."""
        proc.tagged = tag
        for child in proc.children:
            self._tag_with_children(child, tag)

    def change_nice(self, proc, delta):
        """Change process nice value."""
        try:
            new_nice = max(-20, min(19, proc.nice + delta))
            os.setpriority(os.PRIO_PROCESS, proc.pid, new_nice)
        except:
            pass

    def kill_process(self, stdscr, proc):
        """Show kill dialog."""
        # Get tagged processes
        tagged = [p for p in self.proclist.processes.values() if p.tagged]
        if not tagged:
            tagged = [proc]

        # Show signal selection dialog
        signal_num = self.show_signal_dialog(stdscr)
        if signal_num is None:
            return

        for p in tagged:
            try:
                os.kill(p.pid, signal_num)
            except:
                pass

    def show_signal_dialog(self, stdscr):
        """Show a dialog to select a signal."""
        signals = [
            (1, 'SIGHUP'), (2, 'SIGINT'), (3, 'SIGQUIT'),
            (9, 'SIGKILL'), (15, 'SIGTERM'), (17, 'SIGSTOP'),
            (18, 'SIGCONT'), (19, 'SIGSTOP'),
        ]

        h, w = stdscr.getmaxyx()
        dialog_h = min(len(signals) + 4, h - 2)
        dialog_w = 30
        start_y = (h - dialog_h) // 2
        start_x = (w - dialog_w) // 2

        selected = 0

        while True:
            # Draw dialog
            try:
                stdscr.addstr(start_y, start_x, '+' + '-' * (dialog_w - 2) + '+')
                stdscr.addstr(start_y + 1, start_x, '|' + ' Kill with signal '.center(dialog_w - 2) + '|')
                for i, (sig_num, sig_name) in enumerate(signals):
                    row = start_y + 2 + i
                    if row >= start_y + dialog_h - 1:
                        break
                    line = ' %d %-15s' % (sig_num, sig_name)
                    if i == selected:
                        attr = curses.color_pair(COLOR_PANEL_SELECTION_FOCUS) | curses.A_BOLD
                    else:
                        attr = curses.color_pair(COLOR_DEFAULT)
                    stdscr.addstr(row, start_x, '|', curses.color_pair(COLOR_DEFAULT))
                    stdscr.addstr(row, start_x + 1, line.ljust(dialog_w - 2)[:dialog_w-2], attr)
                    stdscr.addstr(row, start_x + dialog_w - 1, '|', curses.color_pair(COLOR_DEFAULT))
                stdscr.addstr(start_y + dialog_h - 1, start_x, '+' + '-' * (dialog_w - 2) + '+')
            except:
                pass

            stdscr.refresh()
            key = stdscr.getch()

            if key == 27:
                return None
            elif key in (curses.KEY_ENTER, 10, 13):
                return signals[selected][0]
            elif key == curses.KEY_UP and selected > 0:
                selected -= 1
            elif key == curses.KEY_DOWN and selected < len(signals) - 1:
                selected += 1

        return None

    def show_user_filter(self, stdscr):
        """Show user selection dialog."""
        # Get list of unique users
        users = sorted(set(p.username for p in self.proclist.processes.values()))
        users = ['(all users)'] + users

        h, w = stdscr.getmaxyx()
        dialog_h = min(len(users) + 4, h - 2)
        dialog_w = 30
        start_y = (h - dialog_h) // 2
        start_x = (w - dialog_w) // 2

        selected = 0
        if self.proclist.filter_user:
            try:
                selected = users.index(self.proclist.filter_user)
            except:
                selected = 0

        while True:
            try:
                stdscr.addstr(start_y, start_x, '+' + '-' * (dialog_w - 2) + '+')
                stdscr.addstr(start_y + 1, start_x, '|' + ' Show user: '.center(dialog_w - 2) + '|')
                for i, user in enumerate(users[:dialog_h - 3]):
                    row = start_y + 2 + i
                    if i == selected:
                        attr = curses.color_pair(COLOR_PANEL_SELECTION_FOCUS) | curses.A_BOLD
                    else:
                        attr = curses.color_pair(COLOR_DEFAULT)
                    stdscr.addstr(row, start_x, '|')
                    stdscr.addstr(row, start_x + 1, (' ' + user).ljust(dialog_w - 2)[:dialog_w - 2], attr)
                    stdscr.addstr(row, start_x + dialog_w - 1, '|')
                stdscr.addstr(start_y + dialog_h - 1, start_x, '+' + '-' * (dialog_w - 2) + '+')
            except:
                pass

            stdscr.refresh()
            key = stdscr.getch()

            if key == 27:
                return
            elif key in (curses.KEY_ENTER, 10, 13):
                if selected == 0:
                    self.proclist.filter_user = None
                else:
                    self.proclist.filter_user = users[selected]
                self.proclist.rebuild_display_list()
                return
            elif key == curses.KEY_UP and selected > 0:
                selected -= 1
            elif key == curses.KEY_DOWN and selected < len(users) - 1:
                selected += 1

    def show_help(self, stdscr):
        """Show help screen."""
        stdscr.clear()
        lines = HELP_TEXT.split('\n')
        h, w = stdscr.getmaxyx()

        try:
            stdscr.addstr(0, 0, lines[0], curses.color_pair(COLOR_PANEL_HEADER) | curses.A_BOLD)
            for i, line in enumerate(lines[1:], 1):
                if i >= h - 1:
                    break
                stdscr.addstr(i, 0, line[:w-1])
            stdscr.addstr(h-1, 0, 'Press any key to return.'.center(w)[:w-1],
                         curses.color_pair(COLOR_FUNCTION_BAR))
        except:
            pass

        stdscr.refresh()
        stdscr.getch()
        stdscr.clear()

    def show_setup(self, stdscr):
        """Show setup screen."""
        categories = ['Display options', 'Header layout', 'Meters', 'Screens', 'Colors']
        selected_cat = 0

        options = {
            'Display options': [
                ('Tree view', False),
                ('Shadow other users\' processes', False),
                ('Hide kernel threads', not self.proclist.show_kernel_threads),
                ('Hide userland process threads', not self.proclist.show_threads),
                ('Show program path', True),
                ('Highlight large numbers in memory counters', True),
                ('Enable the mouse', not self.no_mouse),
                ('Show tabs for screens', True),
            ]
        }

        h, w = stdscr.getmaxyx()

        cat_w = 20

        while True:
            stdscr.erase()

            # Draw header  
            if self.show_meters:
                draw_header(stdscr, self.sysinfo, h, w, True, self.use_unicode, self.monochrome)

            # Draw tab
            try:
                stdscr.addstr(4, 0, ' ' * w)
                stdscr.addstr(4, 2, '[Setup]', curses.color_pair(COLOR_PANEL_HEADER_FOCUS) | curses.A_BOLD)
            except:
                pass

            # Category list
            for i, cat in enumerate(categories):
                try:
                    if i == selected_cat:
                        attr = curses.color_pair(COLOR_PANEL_SELECTION_FOCUS) | curses.A_BOLD
                    else:
                        attr = curses.color_pair(COLOR_DEFAULT)
                    stdscr.addstr(5 + i, 0, cat.ljust(cat_w)[:cat_w], attr)
                except:
                    pass

            # Content area
            cat_name = categories[selected_cat]
            try:
                stdscr.addstr(5, cat_w + 1, cat_name, curses.A_BOLD)
