def init_colors(monochrome=False):
    """Initialize color pairs for the default color scheme."""
    curses.start_color()
    try:
        curses.use_default_colors()
        bg = -1
    except:
        bg = curses.COLOR_BLACK

    if monochrome or not curses.has_colors():
        for i in range(1, 30):
            try:
                curses.init_pair(i, curses.COLOR_WHITE, bg)
            except:
                pass
        return

    def pair(idx, fg, b=bg):
        try:
            curses.init_pair(idx, fg, b)
        except:
            pass

    pair(CP_CPU_LOW, curses.COLOR_BLUE)
    pair(CP_CPU_MED, curses.COLOR_GREEN)
