def format_col_value(col_name, proc, sysinfo, tree_prefix=''):
    """Return the string value for a column."""
    if col_name == 'PID':
        return str(proc.pid)
    elif col_name == 'USER':
        return proc.username[:10]
    elif col_name == 'PRIORITY':
        if proc.priority == -100:
            return 'RT'
        return str(proc.priority)
    elif col_name == 'NICE':
        return str(proc.nice)
    elif col_name == 'M_VIRT':
        return human_size(proc.virt)
    elif col_name == 'M_RESIDENT':
        return human_size(proc.res)
    elif col_name == 'M_SHARE':
        return human_size(proc.shared)
    elif col_name == 'STATE':
        return proc.state
    elif col_name == 'PERCENT_CPU':
        return '%.1f' % proc.cpu_percent
    elif col_name == 'PERCENT_MEM':
        return '%.1f' % proc.mem_percent
    elif col_name == 'TIME':
        return format_time_hundredths(proc.utime + proc.stime)
    elif col_name == 'Command':
        cmd = proc.cmdline if proc.cmdline else proc.comm
        if tree_prefix:
            return tree_prefix + cmd
        return cmd
    elif col_name == 'IO_PRIORITY':
        # Best-effort, round-robin, etc.
        cls = proc.io_prio_class
        prio = proc.io_prio
        cls_names = {0: 'N', 1: 'RT', 2: 'B', 3: 'id'}
        cls_letters = {0: 'N', 1: 'R', 2: 'B', 3: 'I'}
        return '%s%d' % (cls_letters.get(cls, 'B'), prio)
    elif col_name in ('IO_READ_RATE', 'IO_READ_RATE2'):
        return format_rate(proc.io_read_rate)
    elif col_name == 'IO_WRITE_RATE':
        return format_rate(proc.io_write_rate)
    elif col_name == 'PPID':
        return str(proc.ppid)
    elif col_name == 'PGRP':
        return str(proc.pgrp)
    elif col_name == 'SESSION':
        return str(proc.session)
    elif col_name == 'TTY':
        return str(proc.tty)
    elif col_name == 'TPGID':
        return str(proc.tpgid)
    elif col_name == 'MINFLT':
        return str(proc.minflt)
    elif col_name == 'MAJFLT':
        return str(proc.majflt)
    elif col_name == 'NLWP':
        return str(proc.nlwp)
    elif col_name == 'TGID':
        return str(proc.tgid)
    elif col_name == 'PROCESSOR':
        return str(proc.processor)
    elif col_name == 'OOM':
        return str(proc.oom_score)
    elif col_name == 'CTXT':
        return str(proc.ctxt_switches)
    else:
        return '-'


def get_tree_prefix(proc):
    """Build tree prefix string for a process."""
    if proc.depth == 0:
        return ''
    indent = '   ' * (proc.depth - 1)
    return indent + '`- '


def safe_addstr(win, y, x, s, attr=0):
    """Add string to window, clipping to window bounds."""
    try:
        h, w = win.getmaxyx()
        if y < 0 or y >= h or x >= w:
            return
        s = s[:max(0, w - x)]
        if s:
            win.addstr(y, x, s, attr)
    except:
        pass


def safe_addch(win, y, x, ch, attr=0):
    try:
        h, w = win.getmaxyx()
        if y < 0 or y >= h or x >= w - 1:
            return
        win.addch(y, x, ch, attr)
    except:
        pass

