class HtopApp:
    """Main application."""

    def __init__(self, args):
        self.args = args
        self.sysinfo = SystemInfo()
        self.pl = ProcessList(self.sysinfo)

        # Options
        self.delay = 15  # tenths of a second
        if args.delay is not None:
            try:
                d = int(args.delay)
                self.delay = max(1, min(100, d))
            except:
                pass

        self.monochrome = args.no_color
        self.use_unicode = not args.no_unicode
        self.show_meters = not args.no_meters
        self.show_funcbar = not args.no_function_bar
        self.max_iter = args.max_iterations
        self.readonly = args.readonly
        self.no_mouse = args.no_mouse
        self.highlight_changes = args.highlight_changes

        if args.filter:
            self.pl.filter_string = args.filter
        if args.pid:
            pids = set()
            for tok in args.pid.split(','):
                try:
                    pids.add(int(tok.strip()))
                except:
                    pass
            self.pl.filter_pids = pids or None
        if args.user is not None:
            if args.user == '':
                try:
                    self.pl.filter_user = pwd.getpwuid(os.getuid()).pw_name
                except:
                    self.pl.filter_user = str(os.getuid())
            else:
                self.pl.filter_user = args.user
        if args.sort_key:
            self.pl.sort_key = args.sort_key
        if args.tree:
            self.pl.tree_view = True

        # Screen tabs
        # 0 = Main, 1 = I/O
        self.screen_idx = 0
        self.screen_names = ['Main', 'I/O']
        self.screen_col_defs = [MAIN_COL_DEFS, IO_COL_DEFS]

        # UI state
        self.sel = 0         # selected process index
        self.scroll_y = 0    # vertical scroll offset
        self.height = 24
        self.width = 80
        self.iteration = 0
        self.paused = False
        self.search_str = ''
        self.search_mode = False
        self.filter_mode = False

    def run(self, stdscr):
        curses.cbreak()
        curses.noecho()
        stdscr.keypad(True)
        curses.curs_set(0)

        if not self.no_mouse:
            try:
                curses.mousemask(curses.ALL_MOUSE_EVENTS | curses.REPORT_MOUSE_POSITION)
            except:
                pass

        init_colors(self.monochrome)

        # Timeout in ms
        timeout_ms = self.delay * 100
        stdscr.timeout(timeout_ms)

        self.height, self.width = stdscr.getmaxyx()

        # Initial data
        self.sysinfo.update()
        self.pl.update()
        self.iteration = 1

        while True:
            if not self.paused:
                self._draw(stdscr)

            try:
                key = stdscr.getch()
            except KeyboardInterrupt:
                break

            if key == -1:
                # Timeout
                if not self.paused:
                    self.sysinfo.update()
                    self.pl.update()
                    self.iteration += 1
                    if self.max_iter is not None and self.iteration > self.max_iter:
                        break
                continue

            # Resize check
            new_h, new_w = stdscr.getmaxyx()
            if new_h != self.height or new_w != self.width:
                self.height, self.width = new_h, new_w
                stdscr.clear()

            result = self._handle_key(stdscr, key)
            if result == 'quit':
                break

            # Redraw & refresh data
            self.sysinfo.update()
            self.pl.update()
            self.iteration += 1
            if self.max_iter is not None and self.iteration > self.max_iter:
                break

        curses.curs_set(1)

    def _header_rows(self):
        return 3 if self.show_meters else 0

    def _list_start(self):
        return self._header_rows() + 1 + 1  # +1 blank, +1 tab row

    def _list_height(self):
        bottom = 1 if (self.show_funcbar and not self.search_mode and not self.filter_mode) else 0
        return max(1, self.height - self._list_start() - 1 - bottom)  # -1 for column header

    def _draw(self, win):
        win.erase()
        h, w = self.height, self.width

        # Header
        if self.show_meters:
            draw_header(win, self.sysinfo, h, w, True, self.use_unicode)

        hr = self._header_rows()

        # Blank separator line
        safe_addstr(win, hr, 0, ' ' * w)

        # Tab row
        tab_row = hr + 1
        self._draw_tabs(win, tab_row, w)

        # Column header + process list
        list_start = tab_row + 1
        list_h = max(1, h - list_start - (1 if self.show_funcbar else 0))
        self._draw_proc_list(win, list_start, list_h, w)

        # Function / search bar
        if self.show_funcbar:
            frow = h - 1
            if self.search_mode:
                self._draw_search_bar(win, frow, w)
            elif self.filter_mode:
                self._draw_filter_bar(win, frow, w)
            else:
                self._draw_funcbar(win, frow, w)

        win.refresh()

    def _draw_tabs(self, win, row, width):
        x = 0
        for i, name in enumerate(self.screen_names):
            label = ' [%s] ' % name
            if i == self.screen_idx:
                attr = curses.color_pair(CP_PANEL_HEADER) | curses.A_BOLD
            else:
                attr = curses.color_pair(CP_PANEL_HEADER)
            safe_addstr(win, row, x, label, attr)
            x += len(label)

    def _draw_proc_list(self, win, start_row, num_rows, width):
        """Draw column headers and process rows."""
        if num_rows < 1:
            return

        col_defs = self.screen_col_defs[self.screen_idx]
        tree_view = self.pl.tree_view and self.screen_idx == 0

        # Build rendered column list (name, width, right_align, title, sep)
        # For last column, width = remaining
        cols = []
        used = 0
        for idx, (cname, cw, right, title, sep) in enumerate(col_defs):
            if idx == len(col_defs) - 1:
                # Last column: take remaining width
                remaining = max(10, width - used)
                cols.append((cname, remaining, right, title, sep))
            else:
                cols.append((cname, cw, right, title, sep))
                used += cw + len(sep)

        # Draw column header row
        hdr_attr = curses.color_pair(CP_PANEL_HEADER) | curses.A_BOLD
        x = 0
        for cname, cw, right, title, sep in cols:
            # Check if this is the sort column
            if cname == self.pl.sort_key or (cname == 'PERCENT_CPU' and self.pl.sort_key == 'PERCENT_CPU'):
                attr = curses.color_pair(CP_HIGHLIGHT) | curses.A_BOLD
            else:
                attr = hdr_attr

            # Special: in tree view, PID header shows 'PID+'
            disp_title = title
            if cname == 'PID' and tree_view:
                disp_title = 'PID+'

            if right:
                s = disp_title.rjust(cw)[:cw]
            else:
                s = disp_title.ljust(cw)[:cw]

            safe_addstr(win, start_row, x, s, attr)
            x += cw
            if sep:
                safe_addstr(win, start_row, x, sep, hdr_attr)
                x += len(sep)

        # Get visible processes
        procs = self.pl.display_list
        if self.search_str:
            sl = self.search_str.lower()
            procs = [p for p in procs if sl in (p.cmdline or p.comm).lower()]

        total = len(procs)

        # Clamp selection
        self.sel = max(0, min(total - 1, self.sel))

        # Adjust scroll
        list_rows = num_rows - 1  # subtract header
        if total > 0:
            if self.sel < self.scroll_y:
                self.scroll_y = self.sel
            elif self.sel >= self.scroll_y + list_rows:
                self.scroll_y = self.sel - list_rows + 1
        self.scroll_y = max(0, self.scroll_y)

        # Draw process rows
        for row_i in range(list_rows):
            row = start_row + 1 + row_i
            if row >= self.height:
                break
            pidx = self.scroll_y + row_i
            if pidx >= total:
                # Clear row
                safe_addstr(win, row, 0, ' ' * width)
                continue

            proc = procs[pidx]
            selected = (pidx == self.sel)

            # Determine base attribute
            if selected:
                base = curses.color_pair(CP_PROCESS_SELECTED) | curses.A_BOLD
            elif proc.tagged:
                base = curses.color_pair(CP_PROCESS_TAGGED) | curses.A_BOLD
            elif proc.state == 'Z':
                base = curses.color_pair(CP_PROCESS_ZOMBIE) | curses.A_BOLD
            elif proc.state == 'R':
                base = curses.color_pair(CP_PROCESS_RUNNING) | curses.A_BOLD
            elif proc.is_kernel_thread:
                base = curses.color_pair(CP_PROCESS_KERNEL)
            elif proc.is_userland_thread:
                base = curses.color_pair(CP_PROCESS_THREAD)
            else:
                base = curses.color_pair(CP_PROCESS)

            # Build tree prefix for Command column
            tree_prefix = get_tree_prefix(proc) if tree_view else ''

            x = 0
            for cname, cw, right, title, sep in cols:
                val = format_col_value(cname, proc, self.sysinfo,
                                       tree_prefix if cname == 'Command' else '')

                if right and cname != 'Command':
                    s = val.rjust(cw)[:cw]
                else:
                    if cname == 'Command':
                        avail = max(1, width - x)
                        s = val[:avail]
                    else:
                        s = val.ljust(cw)[:cw]

                safe_addstr(win, row, x, s, base)
                x += cw

                if sep and cname != 'Command':
                    safe_addstr(win, row, x, sep, base)
                    x += len(sep)

            # Fill rest of line when selected
            if selected and x < width:
                safe_addstr(win, row, x, ' ' * (width - x), base)

    def _draw_funcbar(self, win, row, width):
        tree_view = self.pl.tree_view
        f5 = 'Tree  ' if not tree_view else 'List  '
        funcs = [
            ('F1', 'Help  '), ('F2', 'Setup '), ('F3', 'Search'),
            ('F4', 'Filter'), ('F5', f5),
            ('F6', 'SortBy'), ('F7', 'Nice -'), ('F8', 'Nice +'),
            ('F9', 'Kill  '), ('F10', 'Quit  '),
        ]
        x = 0
        for fkey, flabel in funcs:
            key_attr = curses.color_pair(CP_FUNCBAR_KEY) | curses.A_BOLD
            lbl_attr = curses.color_pair(CP_FUNCBAR_LABEL)
            safe_addstr(win, row, x, fkey, key_attr)
            x += len(fkey)
            safe_addstr(win, row, x, flabel, lbl_attr)
            x += len(flabel)
            if x >= width:
                break

    def _draw_search_bar(self, win, row, width):
        label = 'Search: '
        safe_addstr(win, row, 0, label, curses.color_pair(CP_FUNCBAR_LABEL) | curses.A_BOLD)
        safe_addstr(win, row, len(label), self.search_str, curses.color_pair(CP_FUNCBAR_LABEL))
        try:
            curses.curs_set(1)
        except:
            pass

    def _draw_filter_bar(self, win, row, width):
        label = 'Filter: '
        safe_addstr(win, row, 0, label, curses.color_pair(CP_FUNCBAR_LABEL) | curses.A_BOLD)
        safe_addstr(win, row, len(label), self.pl.filter_string, curses.color_pair(CP_FUNCBAR_LABEL))
        try:
            curses.curs_set(1)
        except:
            pass

    def _handle_key(self, win, key):
        if self.search_mode:
            return self._search_key(key)
        if self.filter_mode:
            return self._filter_key(key)

        procs = self.pl.display_list
        if self.search_str:
            sl = self.search_str.lower()
            procs = [p for p in procs if sl in (p.cmdline or p.comm).lower()]
        total = len(procs)

        if key == curses.KEY_UP:
            self.sel = max(0, self.sel - 1)
        elif key == curses.KEY_DOWN:
            self.sel = min(total - 1, self.sel + 1)
        elif key == curses.KEY_PPAGE:
            lh = self._list_height()
            self.sel = max(0, self.sel - lh)
            self.scroll_y = max(0, self.scroll_y - lh)
        elif key == curses.KEY_NPAGE:
            lh = self._list_height()
            self.sel = min(total - 1, self.sel + lh)
        elif key == curses.KEY_HOME:
            self.sel = 0
            self.scroll_y = 0
        elif key == curses.KEY_END:
            self.sel = max(0, total - 1)

        elif key == ord('\t'):
            self.screen_idx = (self.screen_idx + 1) % len(self.screen_names)
        elif key == curses.KEY_BTAB:
            self.screen_idx = (self.screen_idx - 1) % len(self.screen_names)

        elif key in (ord('q'), curses.KEY_F10):
            return 'quit'

        elif key in (ord('h'), ord('?'), curses.KEY_F1):
            self._show_help(win)
        elif key in (ord('S'), ord('C'), curses.KEY_F2):
            self._show_setup(win)
        elif key in (ord('/'), curses.KEY_F3):
            self.search_mode = True
            self.search_str = ''
            try:
                curses.curs_set(1)
            except:
                pass
        elif key in (ord('\\'), curses.KEY_F4):
            self.filter_mode = True
            try:
                curses.curs_set(1)
            except:
                pass
        elif key in (ord('t'), curses.KEY_F5):
            self.pl.tree_view = not self.pl.tree_view
            self.pl.rebuild_display_list()
        elif key in (curses.KEY_F6, ord('>'), ord('.')):
            self._show_sort_panel(win)
        elif key == ord('N'):
            self.pl.sort_key = 'PID'
            self.pl.sort_reverse = False
            self.pl.rebuild_display_list()
        elif key == ord('P'):
            self.pl.sort_key = 'PERCENT_CPU'
            self.pl.sort_reverse = True
            self.pl.rebuild_display_list()
        elif key == ord('M'):
            self.pl.sort_key = 'M_RESIDENT'
            self.pl.sort_reverse = True
            self.pl.rebuild_display_list()
        elif key == ord('T'):
            self.pl.sort_key = 'TIME'
            self.pl.sort_reverse = True
            self.pl.rebuild_display_list()
        elif key == ord('I'):
            self.pl.sort_reverse = not self.pl.sort_reverse
            self.pl.rebuild_display_list()
        elif key == ord(' '):
            if procs and 0 <= self.sel < total:
                procs[self.sel].tagged = not procs[self.sel].tagged
                self.sel = min(total - 1, self.sel + 1)
        elif key == ord('c'):
            if procs and 0 <= self.sel < total:
                self._tag_tree(procs[self.sel], True)
        elif key == ord('U'):
            for p in self.pl.processes.values():
                p.tagged = False
        elif key == ord('H'):
            self.pl.show_threads = not self.pl.show_threads
            self.pl.rebuild_display_list()
        elif key == ord('K'):
            self.pl.show_kernel_threads = not self.pl.show_kernel_threads
            self.pl.rebuild_display_list()
        elif key == ord('Z'):
            self.paused = not self.paused
        elif key == ord('#'):
            self.show_meters = not self.show_meters
        elif key == ord('u'):
            self._show_user_filter(win)
        elif key in (ord(']'), curses.KEY_F7):
            if not self.readonly and procs and 0 <= self.sel < total:
                self._renice(procs[self.sel], -1)
        elif key in (ord('['), curses.KEY_F8):
            if not self.readonly and procs and 0 <= self.sel < total:
                self._renice(procs[self.sel], 1)
        elif key in (ord('k'), curses.KEY_F9):
            if not self.readonly and procs:
                self._kill_dialog(win, procs[self.sel] if 0 <= self.sel < total else None)
        elif key == ord('+'):
            if procs and 0 <= self.sel < total:
                procs[self.sel].collapsed = False
                self.pl.rebuild_display_list()
        elif key == ord('-'):
            if procs and 0 <= self.sel < total:
                procs[self.sel].collapsed = True
                self.pl.rebuild_display_list()
        elif key == ord('*'):
            for p in self.pl.processes.values():
                p.collapsed = not p.collapsed
            self.pl.rebuild_display_list()
        elif key == ord('e'):
            if procs and 0 <= self.sel < total:
                self._show_env(win, procs[self.sel])
        elif key == ord('w'):
            if procs and 0 <= self.sel < total:
                self._show_wrap_cmd(win, procs[self.sel])
        elif key == curses.KEY_MOUSE:
            try:
                _, mx, my, _, bstate = curses.getmouse()
                self._handle_mouse(mx, my, bstate)
            except:
                pass
        elif key == curses.KEY_RESIZE:
            self.height, self.width = win.getmaxyx()
            win.clear()
        return None

    def _search_key(self, key):
        if key in (27, curses.KEY_ENTER, 10, 13):
            if key == 27:
                self.search_str = ''
            self.search_mode = False
            try:
                curses.curs_set(0)
            except:
                pass
        elif key in (curses.KEY_BACKSPACE, 127, 8):
            self.search_str = self.search_str[:-1]
        elif 32 <= key < 256:
            self.search_str += chr(key)
        return None

    def _filter_key(self, key):
        if key in (27, curses.KEY_ENTER, 10, 13):
            if key == 27:
                self.pl.filter_string = ''
            self.filter_mode = False
            try:
                curses.curs_set(0)
            except:
                pass
            self.pl.rebuild_display_list()
        elif key in (curses.KEY_BACKSPACE, 127, 8):
            self.pl.filter_string = self.pl.filter_string[:-1]
            self.pl.rebuild_display_list()
        elif 32 <= key < 256:
            self.pl.filter_string += chr(key)
            self.pl.rebuild_display_list()
        return None

    def _handle_mouse(self, mx, my, bstate):
        list_start = self._list_start()
        if my > list_start:
            idx = self.scroll_y + (my - list_start - 1)
            total = len(self.pl.display_list)
            if 0 <= idx < total:
                self.sel = idx

    def _tag_tree(self, proc, tag):
        proc.tagged = tag
        for c in proc.children:
            self._tag_tree(c, tag)

    def _renice(self, proc, delta):
        try:
            new_nice = max(-20, min(19, proc.nice + delta))
            os.setpriority(os.PRIO_PROCESS, proc.pid, new_nice)
        except:
            pass

    def _kill_dialog(self, win, proc):
        signals = [
            (1, 'SIGHUP'), (2, 'SIGINT'), (3, 'SIGQUIT'), (4, 'SIGILL'),
            (6, 'SIGABRT'), (9, 'SIGKILL'), (10, 'SIGUSR1'), (11, 'SIGSEGV'),
            (12, 'SIGUSR2'), (13, 'SIGPIPE'), (14, 'SIGALRM'), (15, 'SIGTERM'),
            (17, 'SIGCHLD'), (18, 'SIGCONT'), (19, 'SIGSTOP'), (20, 'SIGTSTP'),
        ]
        h, w = self.height, self.width
        dh = min(len(signals) + 4, h - 2)
        dw = 28
        sy = (h - dh) // 2
        sx = (w - dw) // 2
        sel = 14  # SIGTERM default

        while True:
            self._draw(win)
            # Draw dialog box
            try:
                win.addstr(sy, sx, '+' + '-' * (dw - 2) + '+')
                title = 'Kill with signal'
                win.addstr(sy + 1, sx, '|' + title.center(dw - 2) + '|')
                for i, (snum, sname) in enumerate(signals):
                    row = sy + 2 + i
                    if row >= sy + dh - 1:
                        break
                    line = ' %2d %-12s' % (snum, sname)
                    attr = (curses.color_pair(CP_PANEL_SELECTED) | curses.A_BOLD
                            if i == sel else curses.color_pair(0))
                    win.addstr(row, sx, '|')
                    win.addstr(row, sx + 1, line.ljust(dw - 2)[:dw - 2], attr)
                    win.addstr(row, sx + dw - 1, '|')
                win.addstr(sy + dh - 1, sx, '+' + '-' * (dw - 2) + '+')
            except:
                pass
            win.refresh()

            k = win.getch()
            if k == 27:
                return
            elif k in (10, 13, curses.KEY_ENTER):
                signum = signals[sel][0]
                tagged = [p for p in self.pl.processes.values() if p.tagged]
                targets = tagged if tagged else ([proc] if proc else [])
                for p in targets:
                    try:
                        os.kill(p.pid, signum)
                    except:
                        pass
                return
            elif k == curses.KEY_UP and sel > 0:
                sel -= 1
            elif k == curses.KEY_DOWN and sel < len(signals) - 1:
                sel += 1

    def _show_user_filter(self, win):
        users = sorted(set(p.username for p in self.pl.processes.values()))
        users = ['(all users)'] + users
        h, w = self.height, self.width
        dh = min(len(users) + 4, h - 2)
        dw = 30
        sy = (h - dh) // 2
        sx = (w - dw) // 2
        sel = 0
        if self.pl.filter_user:
            try:
                sel = users.index(self.pl.filter_user)
            except:
                pass

        while True:
            self._draw(win)
            try:
                win.addstr(sy, sx, '+' + '-' * (dw - 2) + '+')
                win.addstr(sy + 1, sx, '|' + ' Show user: '.center(dw - 2) + '|')
                for i, u in enumerate(users[:dh - 3]):
                    row = sy + 2 + i
                    if row >= sy + dh - 1:
                        break
                    attr = (curses.color_pair(CP_PANEL_SELECTED) | curses.A_BOLD
                            if i == sel else 0)
                    win.addstr(row, sx, '|')
                    win.addstr(row, sx + 1, (' ' + u).ljust(dw - 2)[:dw - 2], attr)
                    win.addstr(row, sx + dw - 1, '|')
                win.addstr(sy + dh - 1, sx, '+' + '-' * (dw - 2) + '+')
            except:
                pass
            win.refresh()

            k = win.getch()
            if k == 27:
                return
            elif k in (10, 13, curses.KEY_ENTER):
                self.pl.filter_user = None if sel == 0 else users[sel]
                self.pl.rebuild_display_list()
                return
            elif k == curses.KEY_UP and sel > 0:
                sel -= 1
            elif k == curses.KEY_DOWN and sel < len(users) - 1:
                sel += 1

    def _show_help(self, win):
        win.clear()
        h, w = self.height, self.width
        lines = HELP_TEXT.split('\n')
        try:
            safe_addstr(win, 0, 0, lines[0],
                        curses.color_pair(CP_PANEL_HEADER) | curses.A_BOLD)
            for i, line in enumerate(lines[1:], 1):
                if i >= h - 1:
                    break
                safe_addstr(win, i, 0, line[:w - 1])
        except:
            pass
        win.refresh()
        win.getch()
        win.clear()

    def _show_setup(self, win):
        """Simple setup screen."""
        categories = ['Display options', 'Header layout', 'Meters', 'Screens', 'Colors']
        cat_sel = 0
        h, w = self.height, self.width
        cat_w = 20

        while True:
            win.erase()
            if self.show_meters:
                draw_header(win, self.sysinfo, h, w)

            hr = self._header_rows()
            safe_addstr(win, hr, 0, ' ' * w)

            # Tab
            tab_row = hr + 1
            safe_addstr(win, tab_row, 2, '[Setup]',
                        curses.color_pair(CP_PANEL_SELECTED) | curses.A_BOLD)

            # Categories
            for i, cat in enumerate(categories):
                row = tab_row + 2 + i
                if row >= h - 1:
                    break
                attr = (curses.color_pair(CP_PANEL_SELECTED) | curses.A_BOLD
                        if i == cat_sel else 0)
                safe_addstr(win, row, 0, cat.ljust(cat_w)[:cat_w], attr)

            # Content
            content_x = cat_w + 1
            cat_name = categories[cat_sel]
            safe_addstr(win, tab_row + 2, content_x, cat_name,
                        curses.A_BOLD)

            if cat_name == 'Colors':
                schemes = ['Default', 'Monochromatic', 'Black on White',
                           'Light Terminal', 'MC', 'Black Night', 'Broken Gray', 'Nord']
                for i, s in enumerate(schemes):
                    row = tab_row + 3 + i
                    if row >= h - 1:
                        break
                    mark = '[x]' if (s == 'Default' and not self.monochrome) else '[ ]'
                    safe_addstr(win, row, content_x, '%s    %s' % (mark, s))

            elif cat_name == 'Display options':
                # "For current screen tab: Main" header
                safe_addstr(win, tab_row + 3, content_x,
                            'For current screen tab: %s' % self.screen_names[self.screen_idx])
                opts = [
                    ('Tree view', self.pl.tree_view),
                    ('- Tree view is always sorted by PID (htop 2 behavior)', False),
                    ('- Tree view is collapsed by default', False),
                    ('Global options:', None),
                    ('Show tabs for screens', True),
                    ('Shadow other users\' processes', False),
                    ('Hide kernel threads', not self.pl.show_kernel_threads),
                    ('Hide userland process threads', not self.pl.show_threads),
                    ('Hide processes running in containers', False),
                    ('Display threads in a different color', True),
                    ('Show custom thread names', False),
                    ('Show program path', True),
                    ('Highlight program "basename"', False),
                    ('Highlight out-dated/removed programs (red) / libraries (yellow)', True),
                    ('Shadow distribution path prefixes', False),
                    ('Merge exe, comm and cmdline in Command', False),
                    ('- Try to find comm in cmdline (when Command is merged)', True),
                    ('- Try to strip exe from cmdline (when Command is merged)', True),
                    ('Highlight large numbers in memory counters', True),
                    ('Leave a margin around header', True),
                    ('Detailed CPU time (System/IO-Wait/Hard-IRQ/Soft-IRQ/Steal/Guest)', False),
                    ('Count CPUs from 1 instead of 0', False),
                    ('Update process names on every refresh', False),
                    ('Add guest time in CPU meter percentage', False),
                    ('Also show CPU percentage numerically', True),
                    ('Also show CPU frequency', False),
                    ('Show cached memory in graph and bar modes', True),
                    ('Enable the mouse', not self.no_mouse),
                    ('[%.1f]  Update interval (in seconds)' % (self.delay / 10.0), None),
                    ('Highlight new and old processes', self.highlight_changes is not None),
                    ('[5]    - Highlight time (in seconds)', None),
                    ('[0]    Hide main function bar (0 - off, 1 - on ESC until next input, 2 - permanently)', None),
                ]
                for i, (name, val) in enumerate(opts):
                    row = tab_row + 4 + i
                    if row >= h - 1:
                        break
                    if val is None:
                        safe_addstr(win, row, content_x, name)
                    else:
                        mark = '[x]' if val else '[ ]'
                        safe_addstr(win, row, content_x, '%s    %s' % (mark, name))

            elif cat_name == 'Meters':
                self._draw_meters_setup(win, tab_row + 3, content_x, h, w)

            # Function bar
            frow = h - 1
            safe_addstr(win, frow, 0, ' ' * (w - 1),
                        curses.color_pair(CP_FUNCBAR_LABEL))
            safe_addstr(win, frow, 64, 'F10',
                        curses.color_pair(CP_FUNCBAR_KEY) | curses.A_BOLD)
            safe_addstr(win, frow, 67, 'Done',
                        curses.color_pair(CP_FUNCBAR_LABEL))

            win.refresh()
            k = win.getch()

            if k in (27, ord('q'), curses.KEY_F10):
                break
            elif k == curses.KEY_UP and cat_sel > 0:
                cat_sel -= 1
            elif k == curses.KEY_DOWN and cat_sel < len(categories) - 1:
                cat_sel += 1

        win.clear()

    def _draw_meters_setup(self, win, start_row, content_x, h, w):
        """Draw the meters setup content."""
        # Column headers
        col1_w = 20
        col2_w = 20
        safe_addstr(win, start_row, content_x, 'Column 1'.ljust(col1_w),
                    curses.A_BOLD)
        safe_addstr(win, start_row, content_x + col1_w + 1, 'Column 2'.ljust(col2_w),
                    curses.A_BOLD)
        safe_addstr(win, start_row, content_x + col1_w + col2_w + 2, 'Available meters',
                    curses.A_BOLD)

        col1_items = ['CPU [Bar]', 'Memory [Bar]', 'Swap [Bar]']
        col2_items = ['Task counter [Text]', 'Load average [Text]', 'Uptime [Text]']
        avail = ['Clock', 'Date', 'Date and Time',
                 'Load averages: 1 minute, 5 minutes, 15 minutes',
                 'Load: average of ready processes in the last minute',
                 'Memory', 'Swap', 'Combined memory and swap usage',
                 'System', 'HugePages', 'Task counter', 'Uptime',
                 'Uptime (seconds)', 'Battery', 'Hostname',
                 'CPUs (1/1): all CPUs']

        for i, item in enumerate(col1_items):
            row = start_row + 1 + i
            if row >= h - 1:
                break
            safe_addstr(win, row, content_x, item[:col1_w])
        for i, item in enumerate(col2_items):
            row = start_row + 1 + i
            if row >= h - 1:
                break
            safe_addstr(win, row, content_x + col1_w + 1, item[:col2_w])
        for i, item in enumerate(avail):
            row = start_row + 1 + i
            if row >= h - 1:
                break
            safe_addstr(win, row, content_x + col1_w + col2_w + 2, item)

    def _show_sort_panel(self, win):
        """Show sort column selection."""
        options = SORT_PANEL_KEYS
        sel = 0
        if self.pl.sort_key in options:
            sel = options.index(self.pl.sort_key)
        h = self.height
        panel_w = max(len(max(options, key=len)) + 2, 18)

        while True:
            self._draw(win)
            try:
                win.addstr(self._list_start(), 0,
                           'Sort by'.ljust(panel_w)[:panel_w],
                           curses.color_pair(CP_PANEL_HEADER) | curses.A_BOLD)
                for i, opt in enumerate(options):
                    row = self._list_start() + 1 + i
                    if row >= h - 1:
                        break
                    attr = (curses.color_pair(CP_PANEL_SELECTED) | curses.A_BOLD
                            if i == sel else 0)
                    win.addstr(row, 0, opt.ljust(panel_w)[:panel_w], attr)
                # Bottom bar
                frow = h - 1
                win.addstr(frow, 0, 'Enter', curses.color_pair(CP_FUNCBAR_KEY) | curses.A_BOLD)
                win.addstr(frow, 5, 'Sort   ', curses.color_pair(CP_FUNCBAR_LABEL))
                win.addstr(frow, 12, 'Esc', curses.color_pair(CP_FUNCBAR_KEY) | curses.A_BOLD)
                win.addstr(frow, 15, 'Cancel', curses.color_pair(CP_FUNCBAR_LABEL))
            except:
                pass
            win.refresh()

            k = win.getch()
            if k == 27:
                break
            elif k in (10, 13, curses.KEY_ENTER):
                self.pl.sort_key = options[sel]
                self.pl.rebuild_display_list()
                break
            elif k == curses.KEY_UP and sel > 0:
                sel -= 1
            elif k == curses.KEY_DOWN and sel < len(options) - 1:
                sel += 1

    def _show_env(self, win, proc):
        try:
            with open('/proc/%d/environ' % proc.pid, 'rb') as f:
                raw = f.read()
            lines = [e.decode('utf-8', errors='replace')
                     for e in raw.split(b'\x00') if e]
        except:
            lines = ['(could not read environment)']

        h, w = self.height, self.width
        scroll = 0
        while True:
            win.clear()
            safe_addstr(win, 0, 0, 'Environment of process %d' % proc.pid,
                        curses.A_BOLD)
            for i, line in enumerate(lines[scroll:scroll + h - 2]):
                safe_addstr(win, i + 1, 0, line[:w - 1])
            safe_addstr(win, h - 1, 0, 'Press q or Esc to return')
            win.refresh()
            k = win.getch()
            if k in (ord('q'), 27):
                break
            elif k == curses.KEY_UP and scroll > 0:
                scroll -= 1
            elif k == curses.KEY_DOWN and scroll < len(lines) - 1:
                scroll += 1
        win.clear()

    def _show_wrap_cmd(self, win, proc):
        cmd = proc.cmdline or proc.comm
        h, w = self.height, self.width
        lines = []
        while cmd:
            lines.append(cmd[:w - 1])
            cmd = cmd[w - 1:]
        win.clear()
        for i, line in enumerate(lines[:h - 2]):
            safe_addstr(win, i, 0, line)
        safe_addstr(win, h - 1, 0, 'Press q or Esc to return')
        win.refresh()
        while True:
            k = win.getch()
            if k in (ord('q'), 27):
                break
        win.clear()


def main():
    parser = argparse.ArgumentParser(add_help=False, allow_abbrev=False)
    parser.add_argument('-C', '--no-color', '--no-colour', action='store_true', default=False)
    parser.add_argument('-d', '--delay', type=str, default=None)
    parser.add_argument('-F', '--filter', type=str, default=None)
    parser.add_argument('--no-function-bar', action='store_true', default=False)
    parser.add_argument('-h', '--help', action='store_true', default=False)
    parser.add_argument('-H', '--highlight-changes', nargs='?', const=5, default=None, type=int)
