                win.addstr(frow, 0, 'Enter', curses.color_pair(CP_FUNCBAR_KEY) | curses.A_BOLD)
                win.addstr(frow, 5, 'Sort   ', curses.color_pair(CP_FUNCBAR_LABEL))
